// snapshot detaches owned rule containers before publishing the schema.
func (draft *MapBuilder[K, V]) snapshot() MapSchema[K, V] {

	return MapSchema[K, V]{
		base:        draft.base.detached(),
		key:         draft.key,
		val:         draft.val,
		constructed: true,
	}
}

// publish erases the schema type only after the typed draft is complete.
func (draft *MapBuilder[K, V]) publish() anySchema {
	return draft.snapshot()
}

// ruleBase exposes immutable rules to another exact-value-type draft.
func (schema MapSchema[K, V]) ruleBase() base[map[K]V] {
	rules := schema.base
	if !schema.constructed {
		rules.problems = append(slices.Clip(rules.problems), "shared MapSchema is uninitialized")
	}
	return rules
}

// Use adds rules from the same published schema role, as a value or nonnil
// pointer, before subsequent local settings. InferSchema contributes type-only
// documentation, not validation or missing child definitions. FromJSONSchema
// provides a separate decoded-JSON API, not a Schema value accepted here.
// Other schema roles are rejected even when their
// value type matches, because importing only their base could lose child rules.
// Schema-level rules accumulate. Overlapping child definitions are construction
// errors, and later local child callbacks cannot replace an imported child.
// Ptr permits an unconstrained scalar adapter to yield to a shared pointee.
// The source remains immutable. Typed nil pointers wrap ErrInvalidSchema.
//
// Example:
//
//	var configure validate.MapBuilderFunc[string, string] = func(rules *validate.MapBuilder[string, string]) {
//	    rules.Use(validate.Map[string, string]())
//	}
//	_ = configure
func (draft *MapBuilder[K, V]) Use(schema Schema[map[K]V]) *MapBuilder[K, V] {
	source := schemaValue(schema)
	reused := reusedDefinition[map[K]V, MapSchema[K, V]](source)
	if importChild(draft.key, reused.key, "Map.Use keys") {
		draft.key = reused.key
		draft.sharedKey = true
	}
	if importChild(draft.val, reused.val, "Map.Use values") {
		draft.val = reused.val
		draft.sharedValue = true
	}
	draft.base = draft.base.inherit(source)
	return draft
}

// PtrBuilder configures a detached PtrSchema during construction.
// Settings return the same draft. Retaining a draft cannot change a schema;
// concurrent mutation of a draft is not supported.
//
// Example:
//
//	var configure validate.PtrBuilderFunc[string] = func(rules *validate.PtrBuilder[string]) {
//	    rules.Required()
//	}
//	_ = configure
type PtrBuilder[T any] struct {
	// base retains shared rules until publication detaches owned containers.
	base[*T]
	// inner retains the optional exact-pointee-type child schema.
	inner anySchema
	// sharedInner protects imported pointee rules from local replacement.
	sharedInner bool
}

// PtrBuilderFunc edits one temporary PtrBuilder. Constructors invoke
// callbacks once, synchronously in order; a nil supplied callback panics.
//
// Example:
//
//	var configure validate.PtrBuilderFunc[string] = func(rules *validate.PtrBuilder[string]) {
//	    rules.Required()
//	}
//	_ = configure
type PtrBuilderFunc[T any] = func(*PtrBuilder[T])

// draftSelf seals the draft's concrete pointer identity for typed children.
func (draft *PtrBuilder[T]) draftSelf() *PtrBuilder[T] {
	return draft
}

// snapshot detaches owned rule containers before publishing the schema.
func (draft *PtrBuilder[T]) snapshot() PtrSchema[T] {
	requireChild(draft.inner, reflect.TypeFor[T](), "Ptr.Value")
	return PtrSchema[T]{
		base:        draft.base.detached(),
		inner:       draft.inner,
		constructed: true,
	}
}

// publish erases the schema type only after the typed draft is complete.
func (draft *PtrBuilder[T]) publish() anySchema {
	return draft.snapshot()
}

// ruleBase exposes immutable rules to another exact-value-type draft.
func (schema PtrSchema[T]) ruleBase() base[*T] {
	rules := schema.base
	if !schema.constructed {
		rules.problems = append(slices.Clip(rules.problems), "shared PtrSchema is uninitialized")
	}
	return rules
}

// Use adds rules from the same published schema role, as a value or nonnil
// pointer, before subsequent local settings. InferSchema contributes type-only
// documentation, not validation or missing child definitions. FromJSONSchema
// provides a separate decoded-JSON API, not a Schema value accepted here.
// Other schema roles are rejected even when their
// value type matches, because importing only their base could lose child rules.
// Schema-level rules accumulate. Overlapping child definitions are construction
// errors, and later local child callbacks cannot replace an imported child.
// Ptr permits an unconstrained scalar adapter to yield to a shared pointee.
// The source remains immutable. Typed nil pointers wrap ErrInvalidSchema.
//
// Example:
//
//	var configure validate.PtrBuilderFunc[string] = func(rules *validate.PtrBuilder[string]) {
//	    rules.Use(validate.Ptr(validate.String[string]()))
//	}
//	_ = configure
func (draft *PtrBuilder[T]) Use(schema Schema[*T]) *PtrBuilder[T] {
	source := schemaValue(schema)
	reused := reusedDefinition[*T, PtrSchema[T]](source)
	if reused.inner != nil {
		if draft.inner != nil && (draft.sharedInner || !emptyPointee[T](draft.inner)) {
			invalidf("Ptr.Use cannot replace an existing pointee definition")
		}
		draft.inner = reused.inner
		draft.sharedInner = true
	}
	draft.base = draft.base.inherit(source)
	return draft
}

