//	        rules.When(func(predicate *validate.ConditionBuilder) {
//	            predicate.Present("Enabled")
//	        }, func(selected *validate.PtrBuilder[string]) {
//	            selected.Required()
//	        })
//	    })
//	})
//	if _, err := schema.JSONSchema(); err != nil { panic(err) }
func (draft *PtrBuilder[T]) When(condition ConditionBuilderFunc, configure ...func(*PtrBuilder[T])) *PtrBuilder[T] {
	observation := buildCondition(condition)
	branch := PtrBuilder[T]{}
	for _, callback := range configure {
		callback(&branch)
	}
	draft.base = draft.when(observation, PtrSchema[T]{
		base:        branch.detached(),
		inner:       branch.inner,
		constructed: true,
	})

	return draft
}

