//	    })
//	})
//	if _, err := schema.JSONSchema(); err != nil { panic(err) }
func (draft *StructBuilder[T]) ProhibitedUnless(configure ...ConditionBuilderFunc) *StructBuilder[T] {

	draft.base = draft.conditional(opProhibitedUnless, buildCondition(configure...))

	return draft
}

// ExcludeIf treats the value as absent, and clears it, when the conditions hold.
// Later ordinary value constraints skip absence, but later presence constraints
// still observe it and can report violations. Unconditional preparation may
// already have run before this rule is evaluated.
//
// Example:
//
//	type Value struct {
//	    Name string
//	}
//	type Form struct {
//	    Value Value
//	    Peer Value
//	    Enabled bool
//	}
//	schema := validate.Struct(func(object *validate.StructBuilder[Form]) {
//	    object.Field("Value", func(rules *validate.StructBuilder[Value]) {
//	        rules.ExcludeIf(func(predicate *validate.ConditionBuilder) {
//	            predicate.Present("Enabled")
//	        })
//	    })
//	})
//	if _, err := schema.JSONSchema(); err != nil { panic(err) }
func (draft *StructBuilder[T]) ExcludeIf(configure ...ConditionBuilderFunc) *StructBuilder[T] {

	draft.base = draft.conditional(opExcludeIf, buildCondition(configure...))

	return draft
}

// EqField requires the value to equal the sibling field of the same type.
//
// Example:
//
//	type Value struct {
//	    Name string
//	}
//	type Form struct {
//	    Value Value
//	    Peer Value
//	    Enabled bool
//	}
//	schema := validate.Struct(func(object *validate.StructBuilder[Form]) {
//	    object.Field("Value", func(rules *validate.StructBuilder[Value]) {
//	        rules.EqField("Peer")
//	    })
//	})
//	if _, err := schema.JSONSchema(); err != nil { panic(err) }
func (draft *StructBuilder[T]) EqField(field string) *StructBuilder[T] {

	draft.base = draft.relate(relEq, field)

	return draft
}

// NeField requires the value to differ from the sibling field of the same type.
//
// Example:
//
//	type Value struct {
//	    Name string
//	}
//	type Form struct {
//	    Value Value
//	    Peer Value
//	    Enabled bool
//	}
//	schema := validate.Struct(func(object *validate.StructBuilder[Form]) {
//	    object.Field("Value", func(rules *validate.StructBuilder[Value]) {
//	        rules.NeField("Peer")
//	    })
//	})
//	if _, err := schema.JSONSchema(); err != nil { panic(err) }
func (draft *StructBuilder[T]) NeField(field string) *StructBuilder[T] {

	draft.base = draft.relate(relNe, field)

	return draft
}

// Describe sets the human-readable description that JSONSchema renders as
