//	        rules.Describe("A display value")
//	    })
//	})
//	if _, err := schema.JSONSchema(); err != nil { panic(err) }
func (draft *StructBuilder[T]) Describe(text string) *StructBuilder[T] {

	draft.base = draft.describe(text)

	return draft
}

// Normalize adds a custom normalizer. It runs before the presence check,
// Default and every rule, in the order written among the normalizers. It
// must return the value it is given or a new one, and must not modify its
// argument. Normalize cannot be used on Map key schemas.
//
// Example:
//
//	type Value struct {
//	    Name string
//	}
//	type Form struct {
//	    Value Value
//	    Peer Value
//	    Enabled bool
//	}
//	schema := validate.Struct(func(object *validate.StructBuilder[Form]) {
//	    object.Field("Value", func(rules *validate.StructBuilder[Value]) {
//	        rules.Normalize(func(value Value) Value {
//	            return value
//	        })
//	    })
//	})
//	if _, err := schema.JSONSchema(); err != nil { panic(err) }
func (draft *StructBuilder[T]) Normalize(fn func(T) T) *StructBuilder[T] {

	draft.base = draft.normalize(fn)

	return draft
}
